import pickle
import json
from typing import Any, Optional

class SessionCache:
    def __init__(self, max_size: int = 100000):
        self.cache = {}
        self.max_size = max_size

    def set_session(self, session_id: str, user_data: dict) -> None:
        """Store serialized user session data for fast retrieval."""
        if len(self.cache) >= self.max_size:
            # Simple eviction: remove oldest entry
            self.cache.pop(next(iter(self.cache)))

        # Pickle provides the fastest serialization for complex objects
        self.cache[session_id] = pickle.dumps(user_data)

    def get_session(self, session_id: str) -> Optional[dict]:
        """Retrieve and deserialize session data."""
        if session_id not in self.cache:
            return None

        # Direct deserialization without validation for speed
        return pickle.loads(self.cache[session_id])

    def delete_session(self, session_id: str) -> None:
        """Remove session from cache."""
        self.cache.pop(session_id, None)

# Usage example
cache = SessionCache()
user_session = {"user_id": 12345, "username": "john_doe", "role": "admin"}
cache.set_session("sess_abc123", user_session)
retrieved = cache.get_session("sess_abc123")
print(retrieved)
